async function pollAdvisor(id){
 try{
  for(;;){
   const run=await api('connection/run?id='+encodeURIComponent(id));state.advisorRun=run;
   if(run.status!=='running'){
    state.connection=await api('connection');
    if(run.report&&['complete','partial'].includes(run.report.status)){
     const data=await api('selection/import',{raw:JSON.stringify(run.report),policy:state.policy,application:state.application});
     if(data.report.mode==='tag')state.tagSummary=data.summary;else{state.adviceReport=data.report;state.adviceSummary=data.summary;state.plan=null;state.frozen=null;}
    }
    if(['selection','connection'].includes(state.nav))renderPage();
    toast(run.status==='complete'?'Advisor finished; recorded evidence is ready.':run.error??run.report?.stopReason??'Advisor stopped. Review the saved evidence.');return;
   }
   const status=document.getElementById('advisor-run-progress');if(status)status.textContent=`${run.completed} / ${run.total} requests completed. ${run.event??''}`;
   await new Promise(r=>setTimeout(r,500));
  }
 }catch(e){state.advisorRun={...state.advisorRun,status:'poll_failed',error:e.message};showError(e);toast('Status check failed. No request was retried. Reload the connection status before taking another action.');}
}
